class Tracked implements AutoCloseable {
    final String value;
    int closes = 0;
    Tracked(String value) { this.value = value; }
    String read() {
        if (closes != 0) throw new IllegalStateException("already closed");
        if (value.equals("FAIL")) throw new IllegalStateException("read");
        return value;
    }
    @Override public void close() { closes++; }
}
public class Main {
    static String readOnce(Tracked resource) {
        // ここを実装する
        return resource.read();
    }
    public static void main(String[] args) {
        Tracked r = new Tracked("ok");
        System.out.println(readOnce(r));
        System.out.println(r.closes);
    }
}

