class Fragile implements AutoCloseable {
    final boolean failClose;
    Fragile(boolean failClose) { this.failClose = failClose; }
    @Override public void close() {
        if (failClose) throw new IllegalStateException("close");
    }
}
public class Main {
    static String result(boolean bodyFail, boolean closeFail) {
        try (Fragile f = new Fragile(closeFail)) {
            if (bodyFail) throw new IllegalArgumentException("body");
            return "ok";
        } catch (RuntimeException e) {
            // ここを実装する
            return e.getMessage();
        }
    }
    public static void main(String[] args) {
        System.out.println(result(true, true));
    }
}

